mapper.select:
SELECT , s.duration, s.file_path FROM t_order_song os LEFT JOIN t_song s ON os.song_id = s.id AND s.deleted = 0 WHERE os.order_id = #{orderId} AND os.deleted = 0
AND os.status = #{status}
ORDER BY os.sort_order ASC, os.create_time ASC

mapper.delete:
DELETE FROM t_order_song
WHERE id = #{orderSongId}
  AND order_id = #{orderId}
  AND status = 0
  AND deleted = 0
